class Session implements Disposable {
  #closed = false;
  constructor(private readonly conn: Connection) {}
  [Symbol.dispose](): void {                 // idempotent; closes owned conn only
    if (this.#closed) return;
    this.#closed = true; this.conn.close();
  }
}
function handle(): void {
  using session = new Session(connect());
  session.roundTrip();                       // disposed on return or throw
}
